package com.autosphere.config;
import com.autosphere.model.*;import com.autosphere.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataSeeder {@Bean CommandLineRunner seed(UserRepository users,VehicleRepository vehicles,CityPriceRepository prices,LeadRepository leads,com.autosphere.repository.UsedCarSaleRepository sales,PasswordEncoder encoder){return args->{if(users.count()==0){users.save(new AppUser("Demo Buyer","buyer@autosphere.demo",encoder.encode("Buyer@123"),Role.BUYER));users.save(new AppUser("Aarav Sharma","sales@autosphere.demo",encoder.encode("Sales@123"),Role.SALES));users.save(new AppUser("Used Car Manager","usedcars@autosphere.demo",encoder.encode("UsedCars@123"),Role.USED_CAR_MANAGER));users.save(new AppUser("AutoSphere Admin","admin@autosphere.demo",encoder.encode("Admin@123"),Role.ADMIN));}if(users.findByEmail("usedcars@autosphere.demo").isEmpty())users.save(new AppUser("Used Car Manager","usedcars@autosphere.demo",encoder.encode("UsedCars@123"),Role.USED_CAR_MANAGER));if(vehicles.count()==0){Vehicle a=new Vehicle();a.stockId="NEW-H-02";a.type="NEW";a.model="Model H";a.variant="ZX automatic";a.fuel="Petrol";a.year=2026;a.kilometres=0;a.exShowroomPrice=1245000;a.imageUrl="https://images.unsplash.com/photo-1617814076367-b759c7d7e738?auto=format&fit=crop&w=1400&q=85";a.description="A confident, comfortable SUV with thoughtful technology and a composed drive.";a=vehicles.save(a);Vehicle b=new Vehicle();b.stockId="UC-1182";b.type="USED";b.model="Model C";b.variant="VX";b.fuel="Diesel";b.year=2022;b.kilometres=41200;b.exShowroomPrice=845000;b.imageUrl="https://images.unsplash.com/photo-1605559424843-9e4c228bf1c2?auto=format&fit=crop&w=1400&q=85";b.description="A well-kept pre-owned vehicle, inspected for a confident next owner.";b=vehicles.save(b);Vehicle c=new Vehicle();c.stockId="UC-1190";c.type="USED";c.model="Model S";c.variant="LX";c.fuel="Petrol";c.year=2021;c.kilometres=58600;c.exShowroomPrice=512000;c.status="BOOKED";c.imageUrl="https://images.unsplash.com/photo-1549317661-bd32c8ce0db2?auto=format&fit=crop&w=1400&q=85";c.description="An approachable city car with practical everyday comfort.";c=vehicles.save(c);for(Vehicle v:new Vehicle[]{a,b,c}){prices.save(new CityPrice(v,"Lucknow",v.type.equals("NEW")?87000:59000,42000,18000));prices.save(new CityPrice(v,"Kanpur",v.type.equals("NEW")?82000:55000,41000,16000));prices.save(new CityPrice(v,"Varanasi",v.type.equals("NEW")?84000:57000,41500,17000));}}if(sales.count()==0){sales.save(new UsedCarSale("Model C",2022,39000,830000,java.time.LocalDate.now().minusMonths(2)));sales.save(new UsedCarSale("Model C",2022,45000,810000,java.time.LocalDate.now().minusMonths(1)));sales.save(new UsedCarSale("Model C",2021,51000,760000,java.time.LocalDate.now().minusMonths(3)));sales.save(new UsedCarSale("Model S",2021,55000,500000,java.time.LocalDate.now().minusMonths(2)));sales.save(new UsedCarSale("Model S",2021,62000,485000,java.time.LocalDate.now().minusMonths(1)));}if(leads.count()==0){Lead demo=new Lead();demo.name="Priya Verma";demo.email="priya@example.demo";demo.phone="9000000001";demo.message="I am interested in the Model H automatic. Can I schedule a test drive this weekend?";demo.vehicleModel="Model H";leads.save(demo);}};}}
